{
 "research_concepts": [
  "PNR (Pick and Roll) failure",
  "PULL_UP shot",
  "Offensive counter-strategy",
  "Play efficiency metrics (points per possession)",
  "Unit-level performance (teams, lineups)",
  "Sequential play analysis"
 ],
 "methodological_questions": [
  "Operationalizing 'failure' for a specific play type (PNR)",
  "Identifying specific shot types (PULL_UP) from play-by-play data",
  "Measuring 'lift' or change in efficiency for sequential plays",
  "Establishing sequential or causal relationships between play events",
  "Aggregating and analyzing performance across multiple units to meet league-wide criteria"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20"
  },
  {
   "id": "FAM:SF-APPA-063",
   "status_as_recorded": "supported",
   "finding": "Median rho +0.539 (IQR +0.245 to +0.750); 62.4% rho>0.4; 88.4% rho>0; 10.5% rho<0. Top-3 median hit 100%; >=2/3 hits 78.9%; median lift +0.4261 PPP; 90.8% positive lift. Bottom-3 median suppression 66.7%."
  },
  {
   "id": "FAM:SF-CHT-020",
   "status_as_recorded": "inconclusive",
   "finding": "T3: no PPP lift, negative mix-carry; did not replicate the in-game adapter PPP lift at Game N+1. Handoff: do not cite ~92.6% or ~96% calibrated numbers for SQ3."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated."
  },
  {
   "id": "FAM:SF-APPM-058",
   "status_as_recorded": "not a hypothesis test",
   "finding": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181)."
  },
  {
   "id": "FAM:SF-APPM-007",
   "status_as_recorded": "inconclusive",
   "finding": "Best +xPPP only R2_hol +0.1204 (lift +0.0054); shot-skills -0.0003."
  },
  {
   "id": "FAM:SF-APPA-034",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Exploit available 33.3%; trap 23.3%; both 6.7%; neither 50.0%; median best edge 3.79%."
  },
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "DRIVE 0.889 -> 0.949 (+0.060); CUT +0.114; PNR +0.087; PULL_UP -0.077; POST_UP -0.032."
  },
  {
   "id": "FAM:SF-APPA-066",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Team-PT lifts are small (ORL vs DET PNR +1.2pp; POR vs SAS all PT lifts negative, e.g. PNR -4.1pp) while player-channel lifts are large on small n (Banchero on Huerter SPOT_UP +8.4pp, n_def=17 / n_off=54; Dort on Coffey  [cut; read_family for the full text]"
  },
  {
   "id": "FAM:SF-CHT-028",
   "status_as_recorded": "untestable",
   "finding": "action_sequences CV=0.612, stability CV=0.919 (unstable); MERGE into possession_flow. Locked 9-pattern set with clutch_performance r(win)=+0.38."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Using play-type classifications without validating underlying assumptions (e.g., assisted flag only on makes)",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Attempting to label on-ball defensive schemes (DROP/ICE/SWITCH) from NBA matchup/PBP fields",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; LIM:small_sample"
  },
  {
   "id": "FAM:SF-APPA-066",
   "what_failed": "Decomposing TOV_FORCE matchup into defender x initiator x PT channels to find positive matchup lift",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:insufficient_exposure"
  },
  {
   "id": "FAM:SF-CHT-028",
   "what_failed": "Using action_sequences as a stable tactical signal",
   "why": "A_unanswerable (question not answerable with the data or design); Stability CV=0.919 and tautological keys (stdev=0); average sample per key 6.9."
  }
 ],
 "evidence_establishes": [
  "Play-type efficiency (PPP) can be a meaningful metric, but its calculation is prone to artifacts if underlying data assumptions are not validated (FAM:SF-PAP-096).",
  "Identifying granular events like defensive schemes or detailed play sequences from raw PBP data can be severely limited by label sparsity and small sample sizes, potentially making such questions untestable (FAM:SF-APPS-058, FAM:SF-APPA-066, FAM:SF-CHT-028).",
  "PNR is a common and quantifiable play type, with its frequency varying by team (FAM:SF-APPM-058).",
  "General play-type PPP can fluctuate across playoff series, with PULL_UP showing a slight decline in one observational study (FAM:SF-APPS-010). However, this was inconclusive and did not establish a causal link or counter-strategy effect."
 ],
 "evidence_does_not_establish": [
  "How to define or identify 'PNR failure' reliably from the available data.",
  "How to reliably identify 'PULL_UP' shots with sufficient accuracy for efficiency calculations.",
  "A robust methodology for linking a 'PNR failure' to a subsequent 'PULL_UP' as a 'counter-strategy'.",
  "The existence or magnitude of 'lift' (PPP change) for a PULL_UP shot specifically as a response to a PNR failure.",
  "Whether such a counter-strategy is 'league-wide' or shows 'lift>0 in >=70% of units with median lift>2pp'.",
  "The specific 'units' (teams, lineups) to be analyzed and how to aggregate across them for league-wide conclusions."
 ],
 "own_inferences": [
  "Defining 'PNR fail' purely based on offensive outcomes (e.g., low PPP, turnover, specific shot outcome on PNR possession) will be more feasible than incorporating complex defensive scheme labels, given historical limitations.",
  "The challenge lies not just in identifying PNR and PULL_UP, but in establishing a clear, measurable temporal and logical link between a 'failure' event and a subsequent 'counter' event within a reasonable timeframe (e.g., same possession, next possession).",
  "The 'lift' metric requires a baseline for comparison (e.g., PULL_UP efficiency in other contexts, or PULL_UP efficiency after successful PNR) or a counterfactual."
 ],
 "uncertainties": [
  "The precise definition of 'PNR fail' is not provided and its operationalization from PBP data is a key unknown.",
  "The accuracy and completeness of 'PULL_UP' shot identification from play-by-play data are not established.",
  "The method for linking a PNR failure to a PULL_UP counter-strategy (e.g., immediate follow-up, within the same possession, next possession) is not specified and impacts measurability.",
  "The definition of a 'unit' (e.g., team, specific lineup) for aggregation is not specified.",
  "The baseline for measuring 'lift' (e.g., compared to average PULL_UP PPP, or PULL_UP PPP not preceded by PNR failure) is not defined."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly highlights the risks associated with granular play-type classification (FAM:SF-PAP-096), the difficulty of deriving complex labels (FAM:SF-APPS-058, FAM:SF-CHT-028), and the general challenges in measuring specific 'lifts' (FAM:SF-APPM-007, FAM:SF-APPS-010). This shifted the decision from 'proceed' to 'do_not_proceed' without significant changes, as the core challenges of defining 'PNR fail' and linking it to a 'PULL_UP' counter are likely untestable with the current data and existing tools, or would require extensive, unvalidated pre-processing that introduces too much risk."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "Defining 'PNR fail' with sufficient precision and reliability from play-by-play data, especially if it involves complex defensive reads, is likely to suffer from low label rates or high error, as seen in attempts to classify defensive schemes (FAM:SF-APPS-058)."
   },
   {
    "code": "EXPOSURE_SPARSITY",
    "text": "The specific sequence of 'PNR fail' followed by a 'PULL_UP' counter might be rare enough that obtaining sufficient sample size for reliable 'lift' calculation across a significant number of 'units' (teams/lineups) is challenging (similar to FAM:SF-APPA-066 on player-channel lifts)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Establishing a causal link between PNR failure and a subsequent PULL_UP as a 'counter' is difficult. Other factors (e.g., shot clock, offensive player skill, defensive rotation, general offensive strategy) could confound the observed lift, making it hard to attribute solely to the PNR failure."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior work directly answers the question of PNR failure leading to a PULL_UP counter with specific lift metrics. Historical evidence highlights challenges in play-type classification, identifying complex events from PBP, and measuring 'lift' reliably in similar contexts. While PNR and PULL_UP are identifiable play types, their sequential and causal relationship as described remains unaddressed."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The definition and reliable identification of 'PNR fail' from play-by-play data is highly susceptible to misclassification or too few instances. Similar issues arose in attempts to label defensive schemes (FAM:SF-APPS-058)."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "The specific event sequence (PNR fail -> PULL_UP) might occur too infrequently across various units to generate enough data points for statistically significant 'lift' measurements for 70% of units and a median lift > 2pp, particularly if 'failure' is a rare outcome."
  },
  {
   "code": "CONFOUNDING",
   "text": "Any observed 'lift' in PULL_UP efficiency after a PNR failure could be confounded by numerous other in-game factors, such as shot clock pressure, defensive scrambling, player skill, or pre-existing offensive strategy, rather than being a direct 'counter' effect. Establishing causality is difficult."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The accuracy of identifying 'PULL_UP' shots from play-by-play data and the precision of PPP calculation for these specific sequences could be compromised if the underlying play-type classification or shot outcome attribution is flawed (as seen in FAM:SF-PAP-096)."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "Evaluating 'lift > 0 in >= 70% of units' implies testing across numerous units, increasing the risk of false positives if not properly accounted for."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.15,
  "untestable": 0.6,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The median Points Per Possession (PPP) 'lift' (increase) of PULL_UP shots when they immediately follow a 'PNR fail' event, compared to PULL_UP shots in a baseline context (e.g., not following a PNR fail or following a successful PNR). This lift should be measured at the unit (team/lineup) level.",
  "unit": "Offensive possessions. Aggregation at the 'unit' level, defined as a specific team-lineup combination (e.g., BOS starters, LAL bench unit) for a given season.",
  "sample": "All NBA 2022-23, 2023-24, 2024-25 regular season and playoff games, and complete 2025-26 regular season data. Only possessions where a 'PNR fail' (defined as PNR resulting in 0 PPP or a turnover within the same possession) is immediately followed by a PULL_UP shot attempt by the same offensive team in the subsequent possession or within the same broken possession.",
  "power": "A minimum of 50 'PNR fail -> PULL_UP' sequences per unit to estimate lift with reasonable precision. The analysis requires enough units (e.g., 20-30 teams, each with multiple relevant lineups) to assess the '>=70% of units' criterion. This is a significant concern given anticipated exposure sparsity.",
  "controls": "Control for confounding factors by comparing 'PNR fail -> PULL_UP' sequences to a control group of PULL_UP shots not preceded by PNR failure, matched on game state (score margin, quarter, shot clock, time remaining), offensive players involved, and defensive scheme if reliably identifiable. This matching will be challenging given data limitations.",
  "falsification": "A falsification test would involve checking if a random (non-PNR fail) event preceding a PULL_UP also shows a similar 'lift', or if PULL_UPs following 'successful PNRs' show a similar or greater lift. If 'PNR fail' is defined as 0 PPP or turnover, check if PULL_UPs after *any* 0 PPP possession show similar lift.",
  "multiplicity": "Adjust p-values for multiple comparisons across units (e.g., using Benjamini-Hochberg procedure) when testing the 'lift > 0' criterion for each unit. The 'median lift > 2pp' criterion will be assessed across all units meeting the 'lift > 0' threshold.",
  "decision_rule": "The hypothesis is supported if: 1. A statistically significant positive median PPP lift (>0) is observed for PULL_UP shots following PNR failure in at least 70% of the identified units. 2. The overall median lift across all units with positive lift is greater than 2pp. A minimum of 20 units must be identified with sufficient data for analysis.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25, 2025-26 (complete regular season), and available playoff data. Play-by-play data (action type, sub-type, clock, period, score, player, shot distance and result), substitution rotation intervals, starters, defensive matchup minutes, and derived play-type possession records."
 }

